#!/usr/bin/env python3
"""Small offline HTML with external PNGs and optional portable ZIP; never embeds image bytes."""
import argparse,html,json,zipfile
from pathlib import Path
from common import BASE,config,profile_fields,output_dir,read_json,write_json,csv_write

HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LFCT · Compact QC</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#21364b;font:14px system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:24px}h1{font-size:28px;margin:6px 0 10px}h2{font-size:18px}p{line-height:1.6}.small{font-size:12px;color:#577085}.layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:16px}.panel,aside,details{background:white;border:1px solid #d1dce6;border-radius:10px;overflow:hidden}aside{padding:16px}.toolbar,.controls{padding:12px;display:flex;align-items:center;gap:9px;flex-wrap:wrap}.view{aspect-ratio:1224/904;max-height:72vh;overflow:hidden;touch-action:none;cursor:grab;background:#f9fbfd}.view:focus-visible{outline:3px solid #3386b5;outline-offset:-3px}.view svg{width:100%;height:100%;display:block}.view:active{cursor:grabbing}button,select{font:inherit;background:white;border:1px solid #c2cfda;border-radius:5px;color:#223b52;padding:5px 8px}button{cursor:pointer}button:hover{background:#edf5fa}button:disabled{opacity:.4}label{display:block;margin:10px 0}input{accent-color:#29749c}#slider{width:100%;margin:0}#which{max-width:100%}#readout{margin-left:auto;font-size:12px}#status{line-height:1.7}.stats{display:flex;gap:15px;margin:16px 0;flex-wrap:wrap}.stats span{background:white;padding:10px 15px;border-radius:7px;border:1px solid #d1dce6}.legend{line-height:1.8;font-size:12px}.table{max-height:350px;overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:7px;text-align:left;border-bottom:1px solid #e0e7ed;white-space:nowrap}th{position:sticky;top:0;background:#f2f6f9}details{padding:15px 18px;margin-top:16px}summary{font-weight:600;cursor:pointer}.bad{color:#b84438}.notice{background:#fff5dc;padding:10px;border-radius:6px;font-size:12px;line-height:1.65;margin:12px 0}#plot{width:100%;height:110px}code{font-size:12px}@media(max-width:850px){.layout{grid-template-columns:1fr}.view{max-height:none}main{padding:14px}}
</style><main><div class="small">LFCT / COMPACT WORKSTREAM / __PROFILE__</div><h1>Cell outlines and isolation QC</h1><p>__INTRO__ Original positions, Spot IDs, Track IDs, and track names are preserved. Overview frames are sampled; only targeted clips are consecutive.</p><div class="stats" id="stats"></div>
<div class="layout"><section class="panel"><div class="toolbar"><select id="which" aria-label="Field or targeted clip"></select><span id="readout"></span></div><div class="view" id="view" tabindex="0" aria-label="Interactive cell contour viewer"></div><div class="controls"><input id="slider" type="range" min="0" max="2" value="0" aria-label="Selected frame"><button id="prev">←</button><button id="play">Play</button><button id="next">→</button><button id="minus" aria-label="Zoom out">−</button><span id="zoom">1.0×</span><button id="plus" aria-label="Zoom in">+</button><button id="reset">Reset view</button></div><p class="small" style="padding:0 12px">Wheel / arrow keys: frames · Ctrl/⌘ + wheel or ±: zoom · Drag: pan · Hover: original IDs and matching/isolation status.</p><div id="plot"></div></section>
<aside><h2>Display</h2><label>Background <select id="background"><option value="phase">Phase</option><option value="rfp">RFP</option><option value="none">Contours only</option></select></label><label>Colors <select id="color"><option value="track">Original Track ID</option><option value="branch">Derived branch</option></select></label><label><input type="checkbox" id="cells" checked> Cell outlines</label><label><input type="checkbox" id="nuclei" checked> Nuclear outlines</label><label><input type="checkbox" id="points" checked> Tracked centroids</label><label><input type="checkbox" id="original"> Original XML outlines</label><label><input type="checkbox" id="unassigned"> Unassigned masks</label><label>Fill <input id="fill" type="range" min="0" max="80" value="25"></label><div class="legend">Dark: cell boundary<br>Turquoise: nuclear boundary<br>Magenta dashes: original outline<br>Gray dashes: unassigned mask<br>Red dot: fails strict isolation<br>Gold ring: targeted trajectory</div><h2>Current frame</h2><div id="status" class="small"></div><div class="notice">Strict candidate: ≥10 consecutive valid frames, ≥10 px clearance, no nearby unresolved detections, and sufficient field-edge clearance. This describes observed frames, not unobserved intervals.</div></aside></div>
<details open><summary>Current detections</summary><div class="table"><table><thead><tr><th>Spot</th><th>Track ID / name</th><th>Cell match</th><th>Nuclear match</th><th>Clearance px</th><th>Exclusions</th></tr></thead><tbody id="rows"></tbody></table></div></details>
<details><summary>Processing results and assumptions</summary><div id="summary"></div><p>Phase and RFP were independently segmented with CPSAM in the existing cpose environment. RFP uses local percentile normalization (128 px); phase uses global percentile normalization. These settings remain provisional until cell-line QC is reviewed.</p><p>Contact clearance is the exact minimum distance between closed unit pixel squares of separate cell masks, including unassigned cells and cells sharing a Track ID. Pixel-edge or corner contact has zero clearance. A containing mask must be claimed by exactly one centroid. Non-containing assignments are excluded from strict isolation. Chains break at splits, merges, temporal gaps, and invalid frames. A missing nuclear mask alone does not fail isolation, but nearby orphan nuclear masks or unmatched centroids within the provisional 50 px guard do.</p><p>Each field retains two lossless compressed uint16 TIFF label stacks with explicit original frame numbers, compressed detection/mask/run tables, source/model/code hashes, validation records, and timing measurements. Source images are temporary except selected PNGs. PNGs are 8-bit visual-QC images with per-frame 1/99.5 percentile normalization; they do not preserve quantitative fluorescence intensity.</p><p>U87 FLD_1 uses the visually reviewed source alignment: source suffix 1 is omitted from both channels; XML 0 maps to suffix 0 and later frames to suffix f+1. The user checked and accepted this alignment before the full run. HEK293 segmentation is known to be poor; the user elected to retain these fields with assignment and isolation exclusions visible.</p><p>IDs are not renumbered. Optional branch colors use a derived branch start Spot ID, and colors are reused. A TrackMate ID can contain many simultaneous cells. No new tracking or artificial mask splitting was performed.</p><p>Keep <code>index.html</code> with its <code>assets/</code> directory, or extract the supplied ZIP. No network or server is needed. All selected PNGs are external assets; no images are embedded in this HTML.</p></details></main>
<script type="application/json" id="data">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),view=$('view');let group=0,index=0,z=1,cx=0,cy=0,timer=null,drag=null,wheel=0;
const colors=['#56B4E9','#E69F00','#009E73','#CC79A7','#F0E442','#D55E00','#8172B3','#80CDC1'];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const item=()=>D.items[group],current=()=>item().frames[index];
function title(s,r){return `Spot ${s.id} · Track ${s.track} (${s.name}) · cell ${r.cell_status} · nucleus ${r.nucleus_status} · clearance ${r.clearance_px===null?(r.cell_label===null?'unassigned':'no other mask'):r.clearance_px.toFixed(2)+' px'} · ${r.exclusions||'eligible observation'}`;}
function tint(s){const key=$('color').value==='track'?s.track:s.branch;return colors[Math.abs(Number(key)||0)%colors.length];}
function transform(){const f=current(),[x,y,w,h]=f.crop,nw=w/z,nh=h/z;cx=Math.max(x+nw/2,Math.min(x+w-nw/2,cx));cy=Math.max(y+nh/2,Math.min(y+h-nh/2,cy));view.firstElementChild.setAttribute('viewBox',`${cx-nw/2} ${cy-nh/2} ${nw} ${nh}`);$('zoom').textContent=z.toFixed(1)+'×';$('minus').disabled=z<=1;$('plus').disabled=z>=12;}
function draw(){const f=current(),[x,y,w,h]=f.crop,bg=$('background').value;let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${x} ${y} ${w} ${h}"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#f9fbfd"/>`;if(bg!=='none')svg+=`<image href="${esc(f.images[bg])}" x="${x}" y="${y}" width="${w}" height="${h}"/>`;
 for(const [kind,nuclear] of [['cells',false],['nuclei',true]]){if(!$(kind).checked)continue;for(const o of f[kind]){const s=o.spot_index===null?null:f.spots[o.spot_index],r=s?f.rows[o.spot_index]:null;if(!s&&!$('unassigned').checked)continue;const path=o.paths.map(loop=>loop.map(([x,y],i)=>(i?'L':'M')+x+','+y).join(' ')+'Z').join(' ');svg+=`<path d="${path}" fill="${s&&!nuclear?tint(s):'none'}" fill-opacity="${Number($('fill').value)/100}" fill-rule="evenodd" stroke="${s?(nuclear?'#36e7da':'#172b3f'):'#758596'}" stroke-width="${nuclear?1.4:1}" vector-effect="non-scaling-stroke" ${s?'':'stroke-dasharray="4 3"'}><title>${esc(s?title(s,r):'Unassigned '+kind+' mask '+o.label)}</title></path>`;}}
 if($('original').checked)for(const s of f.spots)if(s.original.length)svg+=`<polygon points="${s.original.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#ff65cb" stroke-dasharray="4 3" stroke-width="1" vector-effect="non-scaling-stroke"/>`;
 if($('points').checked)f.spots.forEach((s,i)=>{svg+=`<circle cx="${s.x}" cy="${s.y}" r="3" fill="${f.rows[i].eligible?'#152a40':'#dd4037'}" stroke="white" stroke-width=".7"><title>${esc(title(s,f.rows[i]))}</title></circle>`;if(s.branch===item().branch)svg+=`<circle cx="${s.x}" cy="${s.y}" r="9" fill="none" stroke="#ffe95a" stroke-width="2"/>`;});
 view.innerHTML=svg+'</svg>';transform();$('slider').value=index;$('slider').max=item().frames.length-1;$('readout').textContent=`${index+1}/${item().frames.length} · XML frame ${f.frame}`;$('prev').disabled=index===0;$('next').disabled=index===item().frames.length-1;
 $('status').innerHTML=`${f.spots.length} tracked detections<br>${f.rows.filter(r=>r.cell_label!==null).length} assigned cells<br>${f.rows.filter(r=>r.nucleus_label!==null).length} assigned nuclei<br>${f.rows.filter(r=>r.eligible).length} eligible observations<br>Crop: ${w} × ${h} px at (${x}, ${y})`;
 $('rows').innerHTML=f.rows.map(r=>`<tr><td>${r.spot_id}</td><td>${r.track_id} / ${esc(r.track_name)}</td><td>${r.cell_status}</td><td>${r.nucleus_status}</td><td>${r.clearance_px===null?(r.cell_label===null?'unassigned':'no other mask'):r.clearance_px.toFixed(2)}</td><td class="bad">${esc(r.exclusions||'—')}</td></tr>`).join('');plot();}
function plot(){if(item().branch===null){$('plot').innerHTML='<p class="small" style="padding:0 12px">Overview samples are not necessarily consecutive. Choose a targeted clip to inspect clearance over time.</p>';return;}const points=item().frames.map((f,i)=>{const r=f.rows.find(r=>r.branch_start_spot_id===item().branch);return [20+i*560/Math.max(1,item().frames.length-1),90-70*Math.min(100,r?.clearance_px??100)/100];});$('plot').innerHTML=`<svg viewBox="0 0 600 110" width="100%" height="110"><text x="20" y="12" font-size="10">Target clearance (0–100 px; larger/no neighbor plotted at 100)</text><line x1="20" x2="580" y1="83" y2="83" stroke="#d65e56" stroke-dasharray="4 3"/><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#24739f" stroke-width="2"/><circle cx="${points[index][0]}" cy="${points[index][1]}" r="4" fill="#182e43"/><text x="20" y="105" font-size="10">XML ${item().frames[0].frame} → ${item().frames.at(-1).frame}; red line = 10 px</text></svg>`;}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Play';}
function show(i){index=Math.max(0,Math.min(item().frames.length-1,i));draw();}
function choose(i){stop();group=i;index=0;z=1;const [x,y,w,h]=current().crop;cx=x+w/2;cy=y+h/2;view.style.aspectRatio=w+'/'+h;draw();}
function step(d){stop();show(index+d);}
$('which').innerHTML=D.items.map((g,i)=>`<option value="${i}">${esc(g.key)} · ${g.kind==='overview'?'overview':g.kind==='isolated'?'isolated run':'negative control'}${g.branch===null?'':' · branch '+g.branch}</option>`).join('');$('which').onchange=()=>choose(Number($('which').value));$('slider').oninput=()=>{stop();show(Number($('slider').value));};$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('play').onclick=()=>{if(timer){stop();return;}$('play').textContent='Pause';timer=setInterval(()=>show((index+1)%item().frames.length),200);};
const zoom=f=>{z=Math.max(1,Math.min(12,z*f));transform();};$('plus').onclick=()=>zoom(1.25);$('minus').onclick=()=>zoom(.8);$('reset').onclick=()=>{z=1;transform();};for(const id of ['background','color','cells','nuclei','points','original','unassigned','fill'])$(id).oninput=draw;
view.addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey||e.metaKey){zoom(Math.exp(-e.deltaY*.003));return;}wheel+=e.deltaY*(e.deltaMode===1?16:1);if(Math.abs(wheel)>=30){const d=Math.trunc(wheel/30);wheel-=30*d;step(Math.max(-5,Math.min(5,d)));}},{passive:false});
view.addEventListener('keydown',e=>{if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home'){stop();show(0);}else if(e.key==='End'){stop();show(item().frames.length-1);}else step(['ArrowRight','ArrowDown'].includes(e.key)?1:-1);}});
view.addEventListener('pointerdown',e=>{if(e.button!==0)return;view.focus();drag={x:e.clientX,y:e.clientY,cx,cy};view.setPointerCapture(e.pointerId);});view.addEventListener('pointermove',e=>{if(!drag)return;const r=view.getBoundingClientRect(),c=current().crop;cx=drag.cx-(e.clientX-drag.x)*c[2]/z/r.width;cy=drag.cy-(e.clientY-drag.y)*c[3]/z/r.height;transform();});for(const event of ['pointerup','pointercancel','lostpointercapture'])view.addEventListener(event,()=>drag=null);
$('stats').innerHTML=`<span><b>${D.summaries.length}</b> fields</span><span><b>${D.summaries.reduce((n,r)=>n+r.processed_frames,0)}</b> segmented frame pairs</span><span><b>${D.summaries.reduce((n,r)=>n+r.isolated_runs,0)}</b> qualifying runs in tested windows</span><span><b>${D.items.filter(i=>i.kind==='overview').reduce((n,i)=>n+i.frames.length,0)}</b> overview samples</span>`;
$('summary').innerHTML='<table><tr><th>Field</th><th>Frames</th><th>Detections</th><th>Assigned cells</th><th>Nuclei</th><th>Runs ≥10</th></tr>'+D.summaries.map(r=>`<tr><td>${esc(r.key)}</td><td>${r.processed_frames}/${r.total_movie_frames}</td><td>${r.detections}</td><td>${r.assigned_cells}</td><td>${r.assigned_nuclei}</td><td>${r.isolated_runs}</td></tr>`).join('')+'</table>';
choose(0);window.qcTest={get group(){return group;},get index(){return index;},get zoom(){return z;},data:D,choose};
</script></html>'''


def build(profile,bundle=False,run_name=None):
    run_name=run_name or profile
    fields=profile_fields(profile);summaries=[];items=[]
    for key in fields:
        out=output_dir(run_name,key)
        if not (out/'completed.json').exists():raise RuntimeError('Field incomplete: '+key)
        summaries.append(read_json(out/'analysis.json'));items.extend(read_json(out/'qc.json'))
    maxclips=config()['qc']['max_target_clips_report'];overviews=[i for i in items if i['kind']=='overview'];clips=[i for i in items if i['kind']!='overview'][:maxclips];items=overviews+clips
    payload=dict(profile=profile,summaries=summaries,items=items)
    dst=BASE/'reports'/run_name;dst.mkdir(parents=True,exist_ok=True)
    intro='Small end-to-end smoke test; partial stacks are not full-field results.' if profile=='smoke' else 'Selected visual QC from the '+profile+' processing stage.'
    text=HTML.replace('__PROFILE__',html.escape(profile.upper())).replace('__INTRO__',intro).replace('__DATA__',json.dumps(payload,separators=(',',':'),allow_nan=False).replace('</','<\\/'))
    (dst/'index.html').write_text(text)
    csv_write(BASE/'results'/run_name/'summary.csv',summaries)
    selections=[dict(key=i['key'],kind=i['kind'],branch=i['branch'],frame=f['frame'],crop=json.dumps(f['crop']),phase=f['images']['phase'],rfp=f['images']['rfp']) for i in items for f in i['frames']]
    csv_write(dst/'qc_manifest.csv',selections)
    imagefiles={f['images'][c] for item in items for f in item['frames'] for c in ['phase','rfp']}
    for p in imagefiles:assert (dst/p).exists()
    if bundle:
        with zipfile.ZipFile(BASE/'reports'/(run_name+'.zip'),'w') as z:
            z.write(dst/'index.html','index.html',compress_type=zipfile.ZIP_DEFLATED);z.write(dst/'qc_manifest.csv','qc_manifest.csv',compress_type=zipfile.ZIP_DEFLATED)
            for p in sorted(imagefiles):z.write(dst/p,p,compress_type=zipfile.ZIP_STORED)
    result=dict(html_bytes=(dst/'index.html').stat().st_size,png_bytes=sum((dst/p).stat().st_size for p in imagefiles),png_files=len(imagefiles),overview_frames=sum(len(i['frames']) for i in overviews),target_frames=sum(len(i['frames']) for i in clips))
    write_json(BASE/'results'/run_name/'report_size.json',result);print(json.dumps(result,indent=2))
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--profile',default='smoke');p.add_argument('--zip',action='store_true');p.add_argument('--run-name');a=p.parse_args();build(a.profile,a.zip,a.run_name)
